import { defer } from '@enkaku/async';
export function writeTo(write, close, abort) {
    return new WritableStream({
        write,
        close,
        abort
    });
}
export function createArraySink() {
    const done = defer();
    const result = [];
    const stream = new WritableStream({
        write: (value)=>{
            result.push(value);
        },
        close: ()=>done.resolve(result),
        abort: (reason)=>done.reject(reason)
    });
    return [
        stream,
        done.promise
    ];
}
